441	/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
442	function updateKeyValue(content: string, updates: Record<string, string>): string {
443	  const lines = content.split(/\r?\n/);
444	  const seen = new Set<string>();
445	  for (let i = 0; i < lines.length; i++) {
446	    const trimmed = lines[i].trim();
447	    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
448	    const eq = lines[i].indexOf("=");
449	    if (eq < 0) continue;
450	    const key = lines[i].slice(0, eq).trim();
451	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
452	      lines[i] = `${key}=${updates[key]}`;
453	      seen.add(key);
454	    }
455	  }
456	  for (const k of Object.keys(updates)) {
457	    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
458	  }
459	  return lines.join("\n");
460	}
