641	const MINECRAFT_CONTAINER = "mc";
642	/**
643	 * Must track prisma/catalog.ts's minecraft template image tag exactly — see
644	 * that file's own comment on why `:java21` (not bare `:latest`) is required
645	 * for the platform's pinned default VERSION to actually run on a matching
646	 * Java runtime. A version-only settings change recreates the container from
647	 * THIS constant, so drifting the two out of sync would silently reintroduce
648	 * the wrong-Java-version bug for anyone who edits their version in Settings.
649	 */
650	const MINECRAFT_IMAGE = "itzg/minecraft-server:java21";
651	/** Ports + volume exactly as prisma/catalog.ts's minecraft template provisions them. */
652	const MINECRAFT_RUN_FLAGS = "-p 25565:25565 -p 25575:25575 -v /opt/mc:/data --env-file /root/mc.env";
