654	async function applyMinecraft(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
655	  // TODO(paths): confirm the actual install dir/service name for the Minecraft
656	  // image. These candidates cover the common layouts; if none match we soft-fail
657	  // rather than create a stray server.properties in the wrong place.
658	  const path = await remoteLocate(
659	    conn,
660	    [
661	      "/opt/minecraft/server.properties",
662	      "/srv/minecraft/server.properties",
663	      "/home/minecraft/server.properties",
664	      "/minecraft/server.properties",
665	      "/root/minecraft/server.properties",
666	    ],
667	    ["/opt", "/srv", "/home"],
668	    "server.properties"
669	  );
670	  if (!path) {
671	    return { ok: false, applied: [], notes: ["Could not locate server.properties — nothing was changed (restart/redeploy needed once the config path is known)."] };
672	  }
673	
674	  const existing = await sftpRead(sftp, path);
675	  if (existing == null) {
676	    return { ok: false, applied: [], notes: [`server.properties disappeared at ${path} — nothing was changed.`] };
677	  }
678	
679	  // server.properties keys map 1:1 to the schema field keys. VERSION is a
680	  // docker env var, not a server.properties key — it's handled separately
681	  // below via container recreate, not written to this file.
682	  const updates: Record<string, string> = {};
683	  for (const [key, val] of Object.entries(v)) {
684	    if (key === "VERSION") continue;
685	    updates[key] = typeof val === "boolean" ? bool(val) : String(val);
686	  }
687	  const next = updateKeyValue(existing, updates);
688	  await sftpWrite(sftp, path, next);
689	
690	  const applied: string[] = [`Wrote ${Object.keys(updates).length} setting(s) to ${path}.`];
691	  const notes: string[] = [];
692	
693	  // VERSION: itzg's image defaults to tracking Mojang's newest release on every
694	  // container restart unless VERSION is pinned (see prisma/catalog.ts's own
695	  // comment on this field for the live incident that found it). Also checks
696	  // the running image tag against MINECRAFT_IMAGE: a server provisioned before
697	  // the :java21 image tag existed is still on the bare (wrong-Java) image even

698	  // once VERSION itself is correctly pinned — found live 2026-09-06 on the
699	  // very Cobblemon server this field was built for, where VERSION pinned
700	  // clean but the container kept running the stale image's bundled JDK 25.
701	  // Only recreates when either actually differs from what's running, so an
702	  // ordinary gamemode/difficulty change never pays for a full container
703	  // recreate — same reasoning as `applyGameVariant`'s own no-op guard.
704	  const desiredVersion = v["VERSION"] != null ? String(v["VERSION"]) : null;
705	  if (desiredVersion) {
706	    const envMap = await readContainerEnv(conn, MINECRAFT_CONTAINER);
707	    const currentVersion = envMap?.get("VERSION") ?? null;
708	    const currentImage = await readContainerImage(conn, MINECRAFT_CONTAINER);
709	    const imageStale = currentImage !== null && currentImage !== MINECRAFT_IMAGE;
710	    if (envMap && (currentVersion !== desiredVersion || imageStale)) {
711	      envMap.set("VERSION", desiredVersion);
712	      envMap.delete("JAVA_VERSION"); // stale, baked in by whatever image created this container — let the new image set its own
713	      await writeEnvFile(conn, sftp, "/root/mc.env", envMap);
714	      const res = await recreateGameContainer(conn, {
715	        family: "minecraft",
716	        container: MINECRAFT_CONTAINER,
717	        runFlags: MINECRAFT_RUN_FLAGS,
718	        image: MINECRAFT_IMAGE,
719	      });
720	      if (!res.ok) {
721	        notes.push(`Wrote settings, but pinning the Minecraft version failed: ${res.note}`);
722	      } else {
723	        const parts: string[] = [];
724	        if (currentVersion !== desiredVersion) {
725	          parts.push(
726	            currentVersion
727	              ? `pinned Minecraft version to ${desiredVersion} (was ${currentVersion})`
728	              : `pinned Minecraft version to ${desiredVersion} (previously untracked — following Mojang's newest release on every restart)`
729	          );
730	        }
731	        if (imageStale) parts.push(`updated the server image to run the correct Java runtime for this version (was ${currentImage})`);
732	        const summary = parts.join(" and ");
733	        applied.push(`${summary.charAt(0).toUpperCase()}${summary.slice(1)}, and restarted the server.`);
734	      }
735	    }
736	  }
737	
738	  // Best-effort live push via RCON for the live-editable fields; otherwise note a
739	  // restart. Wrapped so RCON problems never fail the apply.
740	  try {
741	    await tryMinecraftRcon(conn, next, v, notes);
742	  } catch (e) {
743	    notes.push("RCON push skipped (unavailable). A restart is required for changes to take effect.");
744	    console.error("[game-config] minecraft rcon error", e);
745	  }
746	
747	  return {
748	    ok: true,
749	    applied,
750	    notes: notes.length ? notes : ["Restart the server for deploy-time settings (hardcore, online-mode) to take effect."],
751	  };
752	}
