754	/**
755	 * Best-effort Minecraft RCON push. Reads rcon config from the (updated)
756	 * server.properties; if RCON is enabled, a password is set, and `mcrcon` exists
757	 * on the box, pushes the live-editable settings. Anything missing → note a restart.
758	 */
759	async function tryMinecraftRcon(conn: Client, props: string, v: Values, notes: string[]): Promise<void> {
760	  const kv = parseKeyValue(props);
761	  const enabled = kv["enable-rcon"] === "true";
762	  const password = kv["rcon.password"] ?? "";
763	  // `rcon.port` is read out of the CUSTOMER'S OWN server.properties, on the
764	  // customer's own VM — an attacker-controlled string in every sense, and one
765	  // this platform never wrote. Only a TCP port number can ever be legitimate, so
766	  // anything that is not one is discarded rather than escaped. `shq` and the
767	  // quoting below are the second and third lines of defence; this is the first,
768	  // and it is the only one that does not depend on getting quoting right.
769	  const port = rconPort(kv["rcon.port"]);
770	  if (!enabled || !password) {
771	    notes.push("RCON is not enabled — restart the server to apply the new settings live.");
772	    return;
773	  }
774	  const which = await execRemote(conn, "command -v mcrcon || true");
775	  if (!which.stdout.trim()) {
776	    notes.push("RCON is enabled but `mcrcon` is not installed — restart to apply live.");
777	    return;
778	  }
779	
780	  // A conservative set of safe live commands. TODO(rcon): expand once the exact
781	  // runtime command set is verified for the target Minecraft build.
782	  const cmds: string[] = [];
783	  if (v["difficulty"] != null) cmds.push(`difficulty ${String(v["difficulty"])}`);
784	  if (v["white-list"] != null) cmds.push(`whitelist ${bool(v["white-list"]) === "true" ? "on" : "off"}`);
785	  if (v["pvp"] != null || v["max-players"] != null || v["motd"] != null) cmds.push("reload");
786	  if (cmds.length === 0) return;
787	
788	  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
789	  // EVERY interpolation is inside single quotes. `shq` escapes a value for use
790	  // INSIDE a single-quoted string — it is not a quoter, and a bare `${shq(x)}`
791	  // is simply an unquoted, word-splitting, metacharacter-honouring shell
792	  // argument. `-P` was written that way, so `rcon.port=1; curl … | sh` in the
793	  // customer's own server.properties ran as root on the hypervisor's SSH client
794	  // target with no further steps required.
795	  //
796	  // The `|| true` that used to end this line is gone. It forced exit 0, so the
797	  // `res.code === 0` test below was a constant and this function reported
798	  // "Pushed live settings via RCON." whether mcrcon worked, refused the
799	  // password, or was never reached. `execRemote` resolves with the real exit
800	  // code rather than rejecting, so nothing here can throw on a non-zero status —
801	  // the note just becomes true.
802	  const res = await execRemote(
803	    conn,
804	    `mcrcon -H 127.0.0.1 -P '${shq(port)}' -p '${shq(password)}' ${quoted} 2>&1`
805	  );
806	  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
807	}
