809	/**
810	 * The RCON port to talk to, from an untrusted `rcon.port` value.
811	 *
812	 * Accepts only a bare 1–65535 decimal; anything else (empty, non-numeric, out of
813	 * range, or carrying a shell payload) falls back to Minecraft's default 25575.
814	 * Returns a string because it is interpolated into a command line, and returning
815	 * the parsed digits — never the caller's original text — is what makes the value
816	 * safe by construction rather than by escaping.
817	 */
818	function rconPort(raw: string | undefined): string {
819	  const n = Number(String(raw ?? "").trim());
820	  if (!Number.isInteger(n) || n < 1 || n > 65535) return "25575";
821	  return String(n);
822	}
